create table if not exists public.patent_search_insights (
  id bigint generated by default as identity primary key,
  display_order smallint not null unique check (display_order > 0),
  title text not null,
  body text not null,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

comment on table public.patent_search_insights is
  'Curated patent-search insights displayed to signed-in users while an analysis is running.';

alter table public.patent_search_insights enable row level security;

revoke all on table public.patent_search_insights from anon, authenticated;
grant select on table public.patent_search_insights to authenticated;

drop policy if exists "Authenticated users can read active patent search insights"
  on public.patent_search_insights;

create policy "Authenticated users can read active patent search insights"
  on public.patent_search_insights
  for select
  to authenticated
  using (is_active);

on conflict (display_order) do update
set
  title = excluded.title,
  body = excluded.body,
  is_active = true;
